return (
    <div className="flex h-screen bg-gray-100">
      {/* Left section with video call */}
      <div className="flex-1 flex-col p-3">
        <div className="bg-black text-white p-4 rounded-3xl">
          <h1 className="text-xl font-bold">Group's Meeting Room - Week 1</h1>
        </div>
  
        <div className="bg-white mt-4 mb-4 p-4 rounded-3xl flex flex-col items-center space-y-4">
          {/* Video area */}
          <div className="flex space-x-4 w-full justify-center">
            <video
              ref={localVideoRef}
              autoPlay
              playsInline
              className="rounded-lg w-full sm:w-xl max-w-lg bg-gray-200"
            />
          </div>
  
          {/* Controls */}
          <div className="flex space-x-4 w-full justify-center">
            <button onClick={toggleMic} className="bg-gray-800 text-white px-4 py-2 rounded-full">
              {isMicOn ? 'Mute Mic' : 'Unmute Mic'}
            </button>
            <button onClick={toggleCamera} className="bg-gray-800 text-white px-4 py-2 rounded-full">
              {isCameraOn ? 'Turn Off Camera' : 'Turn On Camera'}
            </button>
            <button onClick={leaveRoom} className="bg-red-600 text-white px-4 py-2 rounded-full">
              End Meeting
            </button>
          </div>
  
          {/* Remote video thumbnails */}
          <div className="flex space-x-4 w-full justify-center mt-4">
            {[...Array(4)].map((_, index) => (
              <video
                key={index}
                ref={remoteVideoRef}
                autoPlay
                playsInline
                className="rounded-lg w-48 h-36 bg-gray-200"
              />
            ))}
          </div>
        </div>
      </div>
  
      {/* Right section with tabs (chat and participants) */}
      <div className="flex-1 flex flex-col pt-0 p-4 bg-gray-100">
        {/* Tab buttons */}
        <div className="flex justify-between mt-4 mb-4 bg-white rounded-full overflow-hidden shadow">
          <button
            onClick={() => handleTabChange('chat')}
            className={`w-1/2 rounded-full py-2 text-center font-semibold ${activeTab === 'chat' ? 'bg-black text-white' : 'text-black'}`}
          >
            Room Chat
          </button>
          <button
            onClick={() => handleTabChange('participants')}
            className={`w-1/2 py-2 text-center rounded-full font-semibold ${activeTab === 'participants' ? 'bg-black text-white' : 'text-black'}`}
          >
            Participants
          </button>
        </div>
  
        {/* Content area (chat/participants) */}
        <div className="relative flex-1 bg-white rounded-3xl overflow-hidden text-black">
          <AnimatePresence custom={direction}>
            {activeTab === 'chat' && (
              <motion.div
                key="chat"
                custom={direction}
                initial={{ x: direction * 100 + '%' }}
                animate={{ x: 0 }}
                exit={{ x: direction * -100 + '%' }}
                transition={{ duration: 0.4 }}
                className="absolute top-0 left-0 w-full h-full bg-white rounded-xl p-4 overflow-y-auto"
              >
                <div className="space-y-3">
                  {messages.map((msg) => (
                    <div key={msg.id} className={msg.sender === 'You' ? 'text-right' : ''}>
                      <p className="text-sm text-gray-500">{msg.sender}</p>
                      <div
                        className={`inline-block px-3 py-2 rounded-xl ${
                          msg.sender === 'You' ? 'bg-green-100' : 'bg-gray-200'
                        }`}
                      >
                        {msg.text}
                      </div>
                    </div>
                  ))}
                </div>
              </motion.div>
            )}
            {activeTab === 'participants' && (
              <motion.div
                key="participants"
                custom={direction}
                initial={{ x: direction * 100 + '%' }}
                animate={{ x: 0 }}
                exit={{ x: direction * -100 + '%' }}
                transition={{ duration: 0.4 }}
                className="absolute top-0 left-0 w-full h-full bg-white rounded-xl p-4"
              >
                <h2 className="text-xl font-bold mb-4">Participants</h2>
                <ul>
                  <li className="py-2 border-b">Alicia Padlock</li>
                  <li className="py-2 border-b">Sri Veronica</li>
                  <li className="py-2 border-b">You</li>
                </ul>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
  
        {/* Message input */}
        <div className="mt-4 relative">
          <div className="flex items-center bg-white rounded-full px-4 py-2 shadow">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Type message here..."
              className="flex-1 outline-none bg-transparent"
              onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
            />
            <button onClick={() => setShowPicker((v) => !v)} className="text-2xl mr-2">
              😊
            </button>
            <button onClick={sendMessage} className="bg-black text-white rounded-full p-2 text-xl">
              ➤
            </button>
          </div>
          {showPicker && (
            <div className="absolute bottom-14 right-0 z-50" ref={pickerRef}>
              <Picker data={data} onEmojiSelect={addEmoji} />
            </div>
          )}
        </div>
      </div>
    </div>
  );
  